prts.feedbackvariables:
newans:addcol(ans1,matrix([classification1],[classification2],[classification3],[classification4]));
studrows:[];

for j:1 thru 4 do
  if not zeromatrixp(row(newans,j)) then
    studrows:endcons(
      [radcan(ans1[j][1]),radcan(ans1[j][2]),[classification1,classification2,classification3,classification4][j]],
      studrows
    );

cfound:set();

for i:1 thru l do
  block(
    [hit:false],
    for j in studrows do
      if is(equal(radcan(j[1]-class[i][1]),0)) and
         is(equal(radcan(j[2]-class[i][2]),0)) and
         is(equal(j[3],class[i][3]))
      then hit:true,
    if hit then cfound:adjoin(i,cfound)
  );

nclasses:cardinality(cfound);
cscore:nclasses/l;

newans:addcol(ans1,matrix([classification1],[classification2],[classification3],[classification4]));
nentered:0;
for i:1 thru 4 do
  if not zeromatrixp(row(newans,i)) then nentered:nentered+1;

newans:addcol(ans1,matrix([classification1],[classification2],[classification3],[classification4]));
studpts:set();
for j:1 thru 4 do
  if not zeromatrixp(row(newans,j)) then
    studpts:adjoin([radcan(ans1[j][1]),radcan(ans1[j][2])],studpts);

pfound:set();
for i:1 thru l do
  block(
    [hit:false],
    for j in studpts do
      if is(equal(radcan(j[1]-extract[i][1]),0)) and
         is(equal(radcan(j[2]-extract[i][2]),0))
      then hit:true,
    if hit then pfound:adjoin(i,pfound)
  );

npoints:cardinality(pfound);
pscore:npoints/l;
